// One short nightly digest for the owner.
const stats = $('Housekeeping').first().json ?? {};
const health = $input.first().json ?? {};
const body = health.body ?? {};
const healthy = (health.statusCode ?? 0) === 200 && body.status === 'ok';

const lines = [
  '<b>Evaself — ночной отчёт</b>',
  `Пользователей: ${stats.users ?? '?'}`,
  `Агентов Letta: ${stats.agents ?? '?'}`,
  `Необработанных crisis-событий: ${stats.open_crisis ?? '?'}`,
  `Eva Core: ${healthy ? 'ok' : 'ПРОБЛЕМА — ' + JSON.stringify(body.checks ?? {})}`,
];

return [{ json: { text: lines.join('\n') } }];
